-- Translate localisation data (countries, zones, geo zones) into uk-ua / ru-ua.
-- Source: CLDR (unicode.org/cldr) territory + subdivision display names,
-- joined to live data via ISO 3166-1 alpha-2 / ISO 3166-2 codes, plus a
-- curated map for legacy OpenCart zone codes that are not ISO 3166-2.
-- Existing description rows get their name updated; address_format is
-- inherited from the English row for languages that lack one.
-- Idempotent: re-running re-applies the same values (overwrites manual edits
-- of these specific names on re-run — accepted trade-off).

-- Countries (uk)
INSERT INTO `oc_country_description` (`country_id`, `language_id`, `name`, `address_format`)
SELECT c.`country_id`, 2, t.`name`, COALESCE(cden.`address_format`, c.`address_format`)
FROM `oc_country` c
JOIN (
  SELECT `iso2`, `name` FROM (
  SELECT 'AF' AS `iso2`, 'Афганістан' AS `name`
  UNION ALL SELECT 'AL' AS `iso2`, 'Албанія' AS `name`
  UNION ALL SELECT 'DZ' AS `iso2`, 'Алжир' AS `name`
  UNION ALL SELECT 'AS' AS `iso2`, 'Американське Самоа' AS `name`
  UNION ALL SELECT 'AD' AS `iso2`, 'Андорра' AS `name`
  UNION ALL SELECT 'AO' AS `iso2`, 'Ангола' AS `name`
  UNION ALL SELECT 'AI' AS `iso2`, 'Ангілья' AS `name`
  UNION ALL SELECT 'AQ' AS `iso2`, 'Антарктика' AS `name`
  UNION ALL SELECT 'AG' AS `iso2`, 'Антигуа і Барбуда' AS `name`
