  UNION ALL SELECT 'AM' AS `iso2`, 'Вірменія' AS `name`
  UNION ALL SELECT 'AW' AS `iso2`, 'Аруба' AS `name`
  UNION ALL SELECT 'AU' AS `iso2`, 'Австралія' AS `name`
  UNION ALL SELECT 'AT' AS `iso2`, 'Австрія' AS `name`
  UNION ALL SELECT 'AZ' AS `iso2`, 'Азербайджан' AS `name`
  UNION ALL SELECT 'BS' AS `iso2`, 'Багамські Острови' AS `name`
  UNION ALL SELECT 'BH' AS `iso2`, 'Бахрейн' AS `name`
