  ) AS `t1`
) t ON t.`iso2` = c.`iso_code_2`
LEFT JOIN `oc_country_description` cden ON cden.`country_id` = c.`country_id` AND cden.`language_id` = 1
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

-- Countries (ru)
INSERT INTO `oc_country_description` (`country_id`, `language_id`, `name`, `address_format`)
SELECT c.`country_id`, 3, t.`name`, COALESCE(cden.`address_format`, c.`address_format`)
FROM `oc_country` c
JOIN (
  SELECT `iso2`, `name` FROM (
  SELECT 'AF' AS `iso2`, 'Афганистан' AS `name`
  UNION ALL SELECT 'AL' AS `iso2`, 'Албания' AS `name`
  UNION ALL SELECT 'DZ' AS `iso2`, 'Алжир' AS `name`
  UNION ALL SELECT 'AS' AS `iso2`, 'Американское Самоа' AS `name`
  UNION ALL SELECT 'AD' AS `iso2`, 'Андорра' AS `name`
  UNION ALL SELECT 'AO' AS `iso2`, 'Ангола' AS `name`
  UNION ALL SELECT 'AI' AS `iso2`, 'Ангилья' AS `name`
  UNION ALL SELECT 'AQ' AS `iso2`, 'Антарктида' AS `name`
  UNION ALL SELECT 'AG' AS `iso2`, 'Антигуа и Барбуда' AS `name`
  UNION ALL SELECT 'AR' AS `iso2`, 'Аргентина' AS `name`
  UNION ALL SELECT 'AM' AS `iso2`, 'Армения' AS `name`
  UNION ALL SELECT 'AW' AS `iso2`, 'Аруба' AS `name`
  UNION ALL SELECT 'AU' AS `iso2`, 'Австралия' AS `name`
  UNION ALL SELECT 'AT' AS `iso2`, 'Австрия' AS `name`
  UNION ALL SELECT 'AZ' AS `iso2`, 'Азербайджан' AS `name`
