-- Source counts: code=1348, manual=411, manual-name=4, name=1652

-- Geo zones
UPDATE `oc_geo_zone_description` SET `name` = 'VAT Zone', `description` = 'VAT'
WHERE `geo_zone_id` = 3 AND `language_id` = 1 AND (`name` <> 'VAT Zone' OR `description` <> 'VAT');
UPDATE `oc_geo_zone_description` SET `name` = 'Зона ПДВ', `description` = 'ПДВ'
WHERE `geo_zone_id` = 3 AND `language_id` = 2 AND (`name` <> 'Зона ПДВ' OR `description` <> 'ПДВ');
UPDATE `oc_geo_zone_description` SET `name` = 'Зона НДС', `description` = 'НДС'
WHERE `geo_zone_id` = 3 AND `language_id` = 3 AND (`name` <> 'Зона НДС' OR `description` <> 'НДС');

-- Fix junk base names that are still referenced as English fallbacks
UPDATE `oc_zone` SET `name` = 'Badakhshan'
WHERE `zone_id` = 1 AND `name` = '111';
UPDATE `oc_zone_description` SET `name` = 'Badakhshan'
WHERE `zone_id` = 1 AND `language_id` = 1 AND `name` = 'Badakhshan1';
